   31  function esc(s) {
   32    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
   33      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
   34    });
   35  }
   36  function draw() {
   37    var h = '<tr><th>Name</th><th>Qty</th><th>Price</th><th>Updated</th><th></th></tr>';
   38    var total = 0;
   39    for (var i = 0; i < items.length; i++) {
   40      var it = items[i];
   41      h += '<tr><td>' + esc(it.Nm) + '</td><td>' + esc(it.Qty) + '</td><td>' + esc(it.Prc) + '</td><td>' + esc(it.upd) + '</td>' +
   42        '<td><button class="btn" onclick="edit(' + it.ID + ')">edit</button> <button class="btn" onclick="del(' + it.ID + ')">x</button></td></tr>';
   43      var line = (it.Qty * it.Prc).toFixed(2); // 2 decimals for money
   44      total = total + line;
   45    }
   46    document.getElementById('tbl').innerHTML = h;
   47    document.getElementById('tot').innerHTML = 'Total stock value: $' + total;
   48  }
   49  function addItem() {
   50    var o = { nm: document.getElementById('nm').value, qty: document.getElementById('qty').value, prc: document.getElementById('prc').value };
   51    if (editing) o.id = editing;
   52    slop.actions.save(o).then(function () { editing = null; document.getElementById('nm').value = ''; document.getElementById('qty').value = ''; document.getElementById('prc').value = ''; load(); });
   53  }
   54  function edit(id) {
   55    for (var i = 0; i < items.length; i++) if (items[i].ID == id) {
   56      document.getElementById('nm').value = items[i].Nm; document.getElementById('qty').value = items[i].Qty; document.getElementById('prc').value = items[i].Prc;
   57    }
   58    editing = id;
   59  }
   60  function del(id) { if (confirm('delete?')) slop.actions.del({ id: id }).then(load); }
   61    function exportCsv() {
   62      var head = 'name,qty,price,updated';
   63      var lines = items.map(function (r) {
   64        return [r.Nm, r.Qty, r.Prc, r.upd].join(',');
   65      });
