   87        var h = document.createElement('h3');
   88        h.textContent = 'Low stock (Qty < 5)';
   89        box.appendChild(h);
   90        var ul = document.createElement('ul');
   91        var low = r.filter(function (row) { return Number(row.Qty) < 5; });
   92        if (!low.length) {
   93          var li0 = document.createElement('li');
   94          li0.textContent = 'None';
   95          ul.appendChild(li0);
   96        } else {
   97          low.forEach(function (row) {
   98            var li = document.createElement('li');
   99            li.textContent = row.Nm + ' — qty ' + row.Qty;
  100            ul.appendChild(li);
  101          });
  102        }
  103        box.appendChild(ul);
  104        var old = document.getElementById('lowstock');
  105        if (old) old.parentNode.removeChild(old);
  106        document.body.appendChild(box);
  107      });
